# Usage: Rscript scripts/make_man.R
root <- normalizePath(file.path(dirname(sub("--file=", "", grep("--file=", commandArgs(FALSE), value = TRUE)[1])), ".."), winslash = "/")
source(file.path(root, "scripts", "load_package.R")); siw_dev_load(root)
