dir.create(file.path(root, "man"), showWarnings = FALSE)
esc <- function(x) gsub("%", "\\\\%", x)
ns <- parse(file.path(root, "NAMESPACE")); ex <- unlist(lapply(ns, function(e) if (identical(e[[1]], as.name("export"))) vapply(as.list(e)[-1], as.character, "") else NULL))
stopifnot(setequal(ex, names(D)))
for (nm in names(D)) {
  f <- get(nm); a <- formals(f); args <- names(a)
  us <- paste0(nm, "(", paste(vapply(args, function(n) if (is.symbol(a[[n]]) && !nzchar(as.character(a[[n]]))) n else paste0(n, " = ", paste(deparse(a[[n]], width.cutoff = 500), collapse = "")), ""), collapse = ", "), ")")
  items <- paste0("\\item{", args, "}{See the package README and configuration file.}", collapse = "\n")
  writeLines(c(paste0("\\name{", nm, "}"), paste0("\\alias{", nm, "}"), paste0("\\title{", D[[nm]][1], "}"),
    "\\usage{", esc(us), "}", if (length(args)) c("\\arguments{", items, "}"), paste0("\\value{", D[[nm]][3], "}"), paste0("\\description{", D[[nm]][2], "}")), file.path(root, "man", paste0(nm, ".Rd")))
}
cat("man pages:", length(D), "\n")
